// A .frcol and a .frreq written by the core authoring verbs must load through the app's own parse
// path unchanged. The pair is generated by driving the real CLI (the host that wires core's verbs to
// the filesystem) into a temp folder, then loaded exactly the way main.js loads a collection and a
// request: JSON.parse, loadSecrets, and normaliseCollectionConfig / normaliseAction.
//
// The assertion that matters is the re-serialisation: JSON.stringify(doc, null, 4) must return the
// identical string the CLI wrote. That is what proves app-saved and agent-saved files will not churn
// against each other in `git diff` -- normalise must find nothing to fill in, and no key order or
// formatting may shift. "No field is missing" is checked alongside it, so a document that round-trips
// only because the app never completed it would still be caught.
const { test, before, after } = require('node:test');
const assert = require('node:assert/strict');
const path = require('node:path');
const fs = require('node:fs');
const os = require('node:os');
const { execFileSync } = require('node:child_process');
const {
    loadSecrets, normaliseAction, normaliseCollectionConfig, CreateEmptyAction, CreateEmptyCollectionConfig
} = require('@fullyrested/core');

const CLI = path.join(__dirname, '..', '..', 'cli-command', 'dist', 'index.js');
const COLLECTION = 'round trip.frcol';
const REQUEST = 'api/items.frreq';

// No secret of this collection is in the keychain, and the documents the verbs write hold no
// { $secret } reference, so loadSecrets has nothing to fill in -- the same store shape main.js
// passes, without reaching the real keychain from a test.
const emptyKeychain = { get: async () => null, set: async () => { throw new Error('a test must not write to the keychain'); } };

let dir;

// Drives the CLI the way an agent would. Failures carry the CLI's own stdout/stderr, so a broken
// verb is reported as itself rather than as an opaque non-zero exit.
const cli = (...args) => {
    try {
        return execFileSync(process.execPath, [CLI, ...args], { cwd: dir, encoding: 'utf8', stdio: 'pipe' });
    } catch (err) {
        assert.fail(`fullyrested ${args.join(' ')} failed (${err.status}): ${err.stdout ?? ''}${err.stderr ?? ''}`);
    }
};

const read = file => fs.readFileSync(path.join(dir, file), 'utf8');

before(() => {
    assert.ok(fs.existsSync(CLI), `${CLI} is missing: build the CLI (npm --prefix ../cli-command run build) before this suite`);
    dir = fs.realpathSync.native(fs.mkdtempSync(path.join(os.tmpdir(), 'fr-roundtrip-')));

    // A pair with something in every part of the shape the app edits: environments and variables on
    // the collection, and a folder, headers, parameters, a body, validation and a run on the request.
    cli('edit', 'new-collection', '--file', COLLECTION, '--environment', 'Development', 'Production');
    cli('edit', 'select-environment', '-c', COLLECTION, '--name', 'Production');
    cli('edit', 'set-variable', '-c', COLLECTION, '--scope', 'collection', '--name', 'host', '--value', 'example.com');
    cli('edit', 'set-variable', '-c', COLLECTION, '--scope', 'env:Production', '--name', 'host', '--value', 'api.example.com');
    cli('edit', 'set-header', '-c', COLLECTION, '--scope', 'collection', '--name', 'accept', '--value', 'application/json');
    cli('edit', 'new-folder', '-c', COLLECTION, '--path', 'api');
    cli('edit', 'new-request', '-c', COLLECTION, '--path', REQUEST, '--method', 'post', '--url', 'https://{{host}}/items');
    cli('edit', 'set-header', '-c', COLLECTION, '--scope', `request:${REQUEST}`, '--name', 'content-type', '--value', 'application/json');
    cli('edit', 'set-param', '-c', COLLECTION, '--scope', `request:${REQUEST}`, '--name', 'page', '--value', '1');
    cli('edit', 'set-body', '-c', COLLECTION, '--scope', `request:${REQUEST}`, '--content-type', 'application/json', '--text', '{"name":"a"}');
    cli('edit', 'set-validation', '-c', COLLECTION, '--scope', `request:${REQUEST}`, '--type', 'ResponseCode', '--http-code', '201');
    cli('edit', 'new-run', '-c', COLLECTION, '--request', REQUEST, '--name', 'smoke');
    cli('edit', 'set-param', '-c', COLLECTION, '--scope', `run:${REQUEST}#smoke`, '--name', 'page', '--value', '2');
    cli('edit', 'set-validation', '-c', COLLECTION, '--scope', `run:${REQUEST}#smoke`, '--type', 'Headers', '--http-code', '200');
    cli('edit', 'set-validation-header', '-c', COLLECTION, '--scope', `run:${REQUEST}#smoke`, '--name', 'content-type', '--value', 'application/json');
});

after(() => fs.rmSync(dir, { recursive: true, force: true }));

// The collection half of loadCollectionFromFile in main.js
async function loadCollection() {
    const text = read(COLLECTION);
    const parsed = JSON.parse(text);
    const config = normaliseCollectionConfig(await loadSecrets(parsed, emptyKeychain, 'fullyrested-collection-test'));
    return { text, config };
}

// loadRequest in main.js, plus the normaliseAction the renderer applies to what it is handed
async function loadRequest() {
    const text = read(REQUEST);
    const parsed = JSON.parse(text);
    const action = normaliseAction(await loadSecrets(parsed, emptyKeychain, 'fullyrested-request-test'));
    return { text, action };
}

test('a collection the core verbs wrote re-serialises to the identical string', async () => {
    const { text, config } = await loadCollection();
    assert.equal(JSON.stringify(config, null, 4), text);
});

test('a request the core verbs wrote re-serialises to the identical string', async () => {
    const { text, action } = await loadRequest();
    assert.equal(JSON.stringify(action, null, 4), text);
});

test('the loaded collection is missing no field the app expects', async () => {
    const { config } = await loadCollection();
    const complete = normaliseCollectionConfig(CreateEmptyCollectionConfig({ generateGUID: () => 'guid' }));
    assert.deepEqual(Object.keys(config).sort(), Object.keys(complete).sort());
    assert.deepEqual(Object.keys(config.collectionEnvironment).sort(), Object.keys(complete.collectionEnvironment).sort());
    assert.equal(config.environments.length, 2);
    for (const environment of [config.collectionEnvironment, ...config.environments]) {
        assert.deepEqual(Object.keys(environment).sort(), Object.keys(complete.collectionEnvironment).sort());
        assert.deepEqual(Object.keys(environment.auth).sort(), Object.keys(complete.collectionEnvironment.auth).sort());
    }
    // The environment the CLI selected is the one the app would open on
    assert.equal(config.selectedEnvironmentId, config.environments.find(e => e.name == 'Production').id);
});

test('the loaded request is missing no field the app expects', async () => {
    const { action } = await loadRequest();
    const complete = normaliseAction(CreateEmptyAction());
    // An empty action carries no `protocol`; new-request split the https:// off the url into one,
    // so the written document has that key and nothing else beyond the complete shape.
    assert.deepEqual(Object.keys(action).sort(), Object.keys({ ...complete, protocol: '' }).sort());
    assert.deepEqual(Object.keys(action.authentication).sort(), Object.keys(complete.authentication).sort());
    assert.deepEqual(Object.keys(action.body).sort(), Object.keys(complete.body).sort());
    assert.equal(action.runs.length, 1);
    const run = action.runs[0];
    assert.deepEqual(Object.keys(run.authentication).sort(), Object.keys(complete.authentication).sort());
    for (const validation of [action.validation, run.validation])
        assert.ok(validation.type != undefined && validation.headers != undefined
            && validation.body != undefined && validation.httpCode != undefined,
            `validation is incomplete: ${JSON.stringify(validation)}`);
});

// Normalise fills missing fields in place; on a document the verbs wrote there is nothing to fill,
// so a second pass must be a no-op. A normalise that is not idempotent would churn a file on every
// save even when the first round trip happened to match.
test('normalising a second time changes nothing', async () => {
    const { text, config } = await loadCollection();
    assert.equal(JSON.stringify(normaliseCollectionConfig(config), null, 4), text);
    const request = await loadRequest();
    assert.equal(JSON.stringify(normaliseAction(request.action), null, 4), request.text);
});
